def most_common_letter(word: str) -> str:
    counts: dict[str, int] = {}
    for letter in word:
        counts[letter] = counts.get(letter, 0) + 1
    # max keeps the first of equal counts, so sorting breaks ties by letter
    best = max(sorted(counts), key=counts.get)
    return f"{best} {counts[best]}"


word = input().strip()
print(most_common_letter(word))

