#include <iostream>
#include <map>
#include <string>

std::string mostCommonLetter(const std::string& word) {
    std::map<char, int> counts;
    for (char letter : word) {
        counts[letter]++;
    }
    // std::map visits letters in alphabetical order
    char best = 0;
    int bestCount = 0;
    for (const auto& [letter, count] : counts) {
        if (count > bestCount) {
            best = letter;
            bestCount = count;
        }
    }
    return std::string(1, best) + " " + std::to_string(bestCount);
}

int main() {
    std::string word;
    std::cin >> word;
    std::cout << mostCommonLetter(word) << "\n";
    return 0;
}

