package main

import "fmt"

func mostCommonLetter(word string) string {
	counts := make(map[rune]int)
	for _, letter := range word {
		counts[letter]++
	}
	// walk the alphabet in order so ties keep the earlier letter
	best := 'a'
	for letter := 'a'; letter <= 'z'; letter++ {
		if counts[letter] > counts[best] {
			best = letter
		}
	}
	return fmt.Sprintf("%c %d", best, counts[best])
}

func main() {
	var word string
	fmt.Scan(&word)
	fmt.Println(mostCommonLetter(word))
}
